# NAME

SlopDisk - LLM 코딩 에이전트에 의해 작성된 경량 GPT 파티션 테이블 관리 Swift 모듈

# WARNING: NOT FOR PRODUCTION USE

- 실제 디스크랑 연결하지 마십시오. 당신은 좆될 수 있습니다. (진지)

# SYNOPSIS



import Foundation
import SlopDisk

let disk = try SDDiskImage.create(.inMemory, desiredSize: .megabytes(4))
// let disk = try SDDiskImage.open(.file("/tmp/disk-image.img"))
// try disk.refresh()

if disk.partitions.isEmpty {
    print("== NO PARTITIONS ==")
} else {
    for partition in disk.partitions {
        print("Partition #%d: \(partition.begin) ~ \(partition.end) (\(partition.size))")
    }
}

try disk.withTransaction { txn in
    txn.clear()

    txn.addPartition(.megabytes(400), type: .efi, label: "EFI")
    txn.addPartition(.gigabytes(8192), type: .fat32, label: "WIN11ISO")
    // writes partition table and sync()
    try txn.commit()
}




